<?php
/**
 * Registers the WPBP Tools ability category with the WordPress Abilities API.
 */
function wpbp_register_wpbp_tools_category() {
	if ( ! function_exists( 'wp_register_ability_category' ) ) {
		return;
	}

	wp_register_ability_category(
		'wpbp-tools',
		array(
			'label'       => __( 'WPBP Tools', 'wpbp' ),
			'description' => __( 'Abilities provided by the WPBP tools suite.', 'wpbp' ),
		)
	);
}

add_action( 'wp_abilities_api_categories_init', 'wpbp_register_wpbp_tools_category' );

// The site may have already initialized the Abilities API before this code loaded.
if ( did_action( 'wp_abilities_api_categories_init' ) ) {
	wpbp_register_wpbp_tools_category();
}
