    check_ajax_referer( 'wpbp_toggle', '_ajax_nonce' );

    $post_id = isset( $_POST['post_id'] ) ? absint( wp_unslash( $_POST['post_id'] ) ) : 0;

    if ( ! $post_id || ! current_user_can( 'edit_post', $post_id ) ) {
        wp_send_json_error( array( 'message' => 'Forbidden' ), 403 );
    }

    $current_state = get_post_meta( $post_id, 'wpbp_featured', true );
    $new_state     = ( 'on' === $current_state ) ? 'off' : 'on';

    update_post_meta( $post_id, 'wpbp_featured', $new_state );

    wp_send_json_success( array( 'featured' => $new_state ) );
}
