<?php
function wpbp_backup_freshness_site_health_test() {
	$last_backup = (int) get_option( 'wpbp_last_backup', 0 );
	$now         = time();
	$is_fresh    = $last_backup > 0 && $last_backup <= $now && ( $now - $last_backup ) < WEEK_IN_SECONDS;

	if ( $is_fresh ) {
		$status      = 'good';
		$badge_color = 'green';
		$description = '<p>' . esc_html__( 'The most recent backup is less than seven days old.' ) . '</p>';
	} else {
		$status      = 'recommended';
		$badge_color = 'orange';
		$description = '<p>' . esc_html__( 'The most recent backup is older than seven days or has never run. Create a new backup to keep your site protected.' ) . '</p>';
	}

	return array(
		'label'       => esc_html__( 'Backup freshness' ),
		'status'      => $status,
		'badge'       => array(
			'label' => esc_html__( 'Backups' ),
			'color' => $badge_color,
		),
		'description' => $description,
		'test'        => 'wpbp_backup_freshness',
	);
}

