function wpbp_auth_001( string $user_login, string $reset_key ): string {
	$result = \check_password_reset_key( $reset_key, $user_login );

	if ( $result instanceof \WP_User ) {
		return 'valid';
	}

	if ( \is_wp_error( $result ) && 'expired_key' === $result->get_error_code() ) {
		$expiration_filter = static function () {
			return PHP_INT_MAX;
		};

		\add_filter( 'password_reset_expiration', $expiration_filter, PHP_INT_MAX );
		$unexpired_result = \check_password_reset_key( $reset_key, $user_login );
		\remove_filter( 'password_reset_expiration', $expiration_filter, PHP_INT_MAX );

		if ( $unexpired_result instanceof \WP_User ) {
			return 'expired';
		}
	}

	return 'invalid';
}
