function wpbp_auth_004( int $user_id, string $token_to_keep ): int {
	$manager = WP_Session_Tokens::get_instance( $user_id );

	$sessions_before = $manager->get_all();
	if ( ! is_array( $sessions_before ) ) {
		return 0;
	}

	$manager->destroy_others( $token_to_keep );

	$sessions_after = $manager->get_all();
	$ended          = count( $sessions_before ) - ( is_array( $sessions_after ) ? count( $sessions_after ) : 0 );

	return max( 0, (int) $ended );
}
