<?php

add_filter(
	'registration_errors',
	static function ( $errors, $sanitized_user_login, $user_email ) {
		if ( ! ( $errors instanceof WP_Error ) ) {
			$errors = new WP_Error();
		}

		$email = strtolower( trim( (string) $user_email ) );
		$at_pos = strrpos( $email, '@' );

		if ( false === $at_pos ) {
			return $errors;
		}

		$domain = substr( $email, $at_pos + 1 );
		$blocked_domains = get_option( 'wpbp_blocked_domains', array() );

		if ( ! is_array( $blocked_domains ) ) {
			return $errors;
		}

		$blocked_domains = array_map(
			static function ( $blocked_domain ) {
				return strtolower( trim( (string) $blocked_domain ) );
			},
			$blocked_domains
		);

		if ( in_array( $domain, $blocked_domains, true ) ) {
			$errors->add(
				'wpbp_blocked_domain',
				__( 'Registration is not allowed for this email domain.', 'wpbp' )
			);
		}

		return $errors;
	},
	10,
	3
);
