/**
 * Register the WPBP Hero block pattern.
 */
function wpbp_register_hero_pattern() {
	if ( ! function_exists( 'register_block_pattern' ) ) {
		return;
	}

	if ( class_exists( 'WP_Block_Patterns_Registry' ) ) {
		$patterns = WP_Block_Patterns_Registry::get_instance();
		if ( $patterns->is_registered( 'wpbp/hero' ) ) {
			return;
		}
	}

	if ( function_exists( 'register_block_pattern_category' ) ) {
		$category_exists = false;

		if ( class_exists( 'WP_Block_Pattern_Categories_Registry' ) ) {
			$categories      = WP_Block_Pattern_Categories_Registry::get_instance();
			$category_exists = $categories->is_registered( 'featured' );
		}

		if ( ! $category_exists ) {
			register_block_pattern_category(
				'featured',
				array(
					'label' => 'Featured',
				)
			);
		}
	}

	register_block_pattern(
		'wpbp/hero',
		array(
			'title'      => 'WPBP Hero',
			'categories' => array( 'featured' ),
			'content'    => static function () {
				return include __DIR__ . '/patterns/wpbp-hero.php';
			},
		)
	);
}
add_action( 'init', 'wpbp_register_hero_pattern' );
