function wpbp_caching_002( array $values, array $keys, string $group ): array {
    wp_cache_set_multiple( $values, $group );

    $cached = wp_cache_get_multiple( $keys, $group );
    $result = array();

    foreach ( $keys as $key ) {
        $result[ $key ] = array_key_exists( $key, $cached ) ? $cached[ $key ] : false;
    }

    return $result;
}
