<?php
function wpbp_comments_users_006( int $user_id, string $new_password, string $session_token ): bool {
	$user = get_userdata( $user_id );
	if ( ! $user ) {
		return false;
	}

	$result = wp_update_user(
		array(
			'ID'        => $user_id,
			'user_pass' => $new_password,
		)
	);

	if ( is_wp_error( $result ) || (int) $result !== $user_id ) {
		return false;
	}

	clean_user_cache( $user_id );
	$updated_user = get_userdata( $user_id );
	if ( ! $updated_user || ! wp_check_password( $new_password, $updated_user->user_pass, $user_id ) ) {
		return false;
	}

	$session_manager = WP_Session_Tokens::get_instance( $user_id );
	$session_manager->destroy_others( $session_token );

	return true;
}
