function wpbp_connectors_api_006( string $type ): array {
    $ids = array();

    foreach ( wp_get_connectors() as $key => $connector ) {
        $connector_type = null;

        if ( is_array( $connector ) ) {
            if ( isset( $connector['type'] ) ) {
                $connector_type = $connector['type'];
            }
        } elseif ( is_object( $connector ) ) {
            if ( isset( $connector->type ) ) {
                $connector_type = $connector->type;
            } elseif ( is_callable( array( $connector, 'get_type' ) ) ) {
                $connector_type = $connector->get_type();
            }
        }

        if ( $connector_type !== $type ) {
            continue;
        }

        $id = null;

        if ( is_array( $connector ) && isset( $connector['id'] ) ) {
            $id = $connector['id'];
        } elseif ( is_object( $connector ) ) {
            if ( isset( $connector->id ) ) {
                $id = $connector->id;
            } elseif ( is_callable( array( $connector, 'get_id' ) ) ) {
                $id = $connector->get_id();
            }
        }

        if ( null === $id ) {
            $id = $key;
        }

        $ids[] = (string) $id;
    }

    sort( $ids, SORT_STRING );

    return $ids;
}
