function wpbp_dates_time_005( string $utc_datetime ): string {
    $date = DateTimeImmutable::createFromFormat( '!Y-m-d H:i:s', $utc_datetime, new DateTimeZone( 'UTC' ) );

    if ( ! $date ) {
        return '';
    }

    $timezone_string = get_option( 'timezone_string' );

    if ( $timezone_string ) {
        $timezone = new DateTimeZone( $timezone_string );
    } else {
        $offset = (float) get_option( 'gmt_offset', 0 );

        if ( 0.0 === $offset ) {
            $timezone = new DateTimeZone( 'UTC' );
        } else {
            $hours   = (int) $offset;
            $minutes = abs( (int) ( ( $offset - $hours ) * 60 ) );
            $sign    = $offset < 0 ? '-' : '+';

            $timezone = new DateTimeZone( sprintf( '%s%02d:%02d', $sign, abs( $hours ), $minutes ) );
        }
    }

    return $date->setTimezone( $timezone )->format( 'c' );
}
