    $count = 0;
    $wrapper_attributes = preg_replace_callback(
        '/\bclass="([^"]*)"/',
        static function ( $matches ) {
            return 'class="promo' . ( '' !== $matches[1] ? ' ' . $matches[1] : '' ) . '"';
        },
        $wrapper_attributes,
        1,
