function wpbp_gb_interactivity_api_009( array $settings ): array {
	$namespace = 'wpbp/merge';
	$state     = \wp_interactivity_state( $namespace );

	if ( ! is_array( $state ) ) {
		$state = array();
	}

	$existing_settings = array();
	if ( isset( $state['settings'] ) && is_array( $state['settings'] ) ) {
		$existing_settings = $state['settings'];
	}

	$state['settings'] = array_replace_recursive( $existing_settings, $settings );

	\wp_interactivity_state( $namespace, $state );

	return \wp_interactivity_state( $namespace );
}
