<?php
function wpbp_html_api_001( string $html ): string {
    $site_parts = \wp_parse_url( \home_url() );
    $site_host  = ( \is_array( $site_parts ) && isset( $site_parts['host'] ) )
        ? \strtolower( $site_parts['host'] )
        : '';

    $processor = new \WP_HTML_Tag_Processor( $html );
    $changed   = false;

    while ( $processor->next_tag( array( 'tag_name' => 'A' ) ) ) {
        $href = $processor->get_attribute( 'href' );
        if ( ! \is_string( $href ) ) {
            continue;
        }

        $href = \trim( $href );
        if ( '' === $href || 0 === \stripos( $href, 'mailto:' ) ) {
            continue;
        }

        $url_parts = \wp_parse_url( $href );
        if (
            ! \is_array( $url_parts ) ||
            ! isset( $url_parts['host'] ) ||
            '' === $url_parts['host']
        ) {
            continue;
        }

        $anchor_host = \strtolower( $url_parts['host'] );
        if ( $anchor_host === $site_host ) {
            continue;
        }

        $rel         = $processor->get_attribute( 'rel' );
        $has_noopener = false;

        if ( \is_string( $rel ) ) {
            $rel_lower = \strtolower( $rel );
            $rel_lower = \str_replace(
                array( "\t", "\n", "\r", "\f", "\v" ),
                ' ',
                $rel_lower
            );
            $has_noopener = \in_array( 'noopener', \explode( ' ', $rel_lower ), true );
        }

        if ( $has_noopener ) {
            continue;
        }

        if ( \is_string( $rel ) && '' !== \trim( $rel ) ) {
            $processor->set_attribute( 'rel', \rtrim( $rel ) . ' noopener' );
        } else {
            $processor->set_attribute( 'rel', 'noopener' );
        }

        $changed = true;
    }

    return $changed ? $processor->get_updated_html() : $html;
}
