function wpbp_html_api_004( string $html ): array {
	$outline = array();

	if ( ! class_exists( 'WP_HTML_Processor' ) ) {
		return $outline;
	}

	$processor = WP_HTML_Processor::create_full_parser( $html );
	if ( ! $processor ) {
		return $outline;
	}

	$heading_tags = array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' );
	$current      = null;
	$current_tag  = null;

	while ( $processor->next_token() ) {
		$token_type = $processor->get_token_type();

		if ( '#tag' === $token_type ) {
			$tag       = strtolower( (string) $processor->get_tag() );
			$is_closer = $processor->is_tag_closer();

			if ( in_array( $tag, $heading_tags, true ) ) {
				if ( ! $is_closer ) {
					if ( null !== $current ) {
						$outline[] = $current;
					}

					$id = $processor->get_attribute( 'id' );

					$current = array(
						'level' => (int) substr( $tag, 1 ),
						'text'  => '',
						'id'    => is_string( $id ) ? $id : '',
					);
					$current_tag = $tag;
				} elseif ( null !== $current && $current_tag === $tag ) {
					$outline[] = $current;
					$current     = null;
					$current_tag = null;
				}
			}
		} elseif ( '#text' === $token_type && null !== $current ) {
			$current['text'] .= (string) $processor->get_modifiable_text();
		}
	}

	if ( null !== $current ) {
		$outline[] = $current;
	}

	return $outline;
}
