<?php

function wpbp_html_api_009( string $html ): array {
	$processor = WP_HTML_Processor::create_fragment( $html );
	if ( null === $processor ) {
		return array();
	}

	$comments = array();

	while ( $processor->next_token() ) {
		if ( '#comment' !== $processor->get_token_type() ) {
			continue;
		}

		if ( method_exists( $processor, 'get_comment_data' ) ) {
			$text = $processor->get_comment_data();
		} else {
			$text = $processor->get_modifiable_text();
		}

		$text = (string) $text;

		if ( 0 === strpos( $text, ' wp:' ) || 0 === strpos( $text, ' /wp:' ) ) {
			continue;
		}

		$comments[] = array(
			'type'         => $processor->get_token_type(),
			'comment_type' => $processor->get_comment_type(),
			'text'         => $text,
		);
	}

	return $comments;
}
