function wpbp_html_api_010( string $raw_href ): bool {
	$decoded = WP_HTML_Decoder::decode_attribute( $raw_href );

	$decoded = trim( $decoded, "\x00..\x20" );
	$decoded = str_replace( array( "\t", "\n", "\r" ), '', $decoded );

	if ( strlen( $decoded ) < 11 ) {
		return false;
	}

	$scheme = 'javascript:';

	for ( $i = 0; $i < 11; $i++ ) {
		$char = $decoded[ $i ];

		if ( $char >= 'A' && $char <= 'Z' ) {
			$char = chr( ord( $char ) + 32 );
		}

		if ( $char !== $scheme[ $i ] ) {
			return false;
		}
	}

	return true;
}
