function wpbp_http_api_004( string $url ): array {
    $response = wp_remote_get( $url );

    if ( is_wp_error( $response ) ) {
        return array(
            'type'  => '',
            'rate'  => 0,
            'links' => array(),
            'code'  => 0,
        );
    }

    $type_header = wp_remote_retrieve_header( $response, 'content-type' );
    if ( is_array( $type_header ) ) {
        $type_header = reset( $type_header );
    }
    $type = is_string( $type_header ) ? $type_header : '';

    $rate_header = wp_remote_retrieve_header( $response, 'x-wpbp-rate' );
    if ( is_array( $rate_header ) ) {
        $rate_header = reset( $rate_header );
    }
    $rate = ( is_string( $rate_header ) || is_numeric( $rate_header ) ) ? (int) $rate_header : 0;

    $link_header = wp_remote_retrieve_header( $response, 'link' );
    if ( is_array( $link_header ) ) {
        $links = array_values( $link_header );
    } elseif ( is_string( $link_header ) && $link_header !== '' ) {
        $links = array( $link_header );
    } else {
        $links = array();
    }

    $code = (int) wp_remote_retrieve_response_code( $response );

    return array(
        'type'  => $type,
        'rate'  => $rate,
        'links' => $links,
        'code'  => $code,
    );
}
