/**
 * Plugin Name: WPBP Reader Settings
 * Description: Maintains reader settings and upgrades legacy perPage settings.
 * Version: 2.0.0
 * Author: WPBP
 */

define( 'WPBP_READER_CURRENT_VERSION', 2 );

function wpbp_reader_activate() {
    $existing = get_option( 'wpbp_reader_settings', null );
    if ( null === $existing ) {
        update_option(
            'wpbp_reader_settings',
            array(
                'version'     => WPBP_READER_CURRENT_VERSION,
                'per_page'    => 10,
                'show_covers' => true,
            )
        );
    }
}

function wpbp_reader_maybe_upgrade() {
    $settings = get_option( 'wpbp_reader_settings', null );
    if ( null === $settings ) {
        return;
    }

    if ( ! is_array( $settings ) ) {
        $settings = array();
    }

    $current_version = WPBP_READER_CURRENT_VERSION;
    $stored_version  = isset( $settings['version'] ) ? (int) $settings['version'] : 0;

    if ( $stored_version >= $current_version ) {
        return;
    }

    $per_page = 10;
    if ( isset( $settings['perPage'] ) && is_numeric( $settings['perPage'] ) ) {
        $per_page = (int) $settings['perPage'];
    } elseif ( isset( $settings['per_page'] ) && is_numeric( $settings['per_page'] ) ) {
        $per_page = (int) $settings['per_page'];
    }

    $settings['version']  = $current_version;
    $settings['per_page'] = $per_page;

    if ( ! isset( $settings['show_covers'] ) ) {
        $settings['show_covers'] = true;
    }

    unset( $settings['perPage'] );

    update_option( 'wpbp_reader_settings', $settings );

    $upgrades = (int) get_option( 'wpbp_reader_upgrades', 0 );
    update_option( 'wpbp_reader_upgrades', $upgrades + 1 );
}

function wpbp_reader_uninstall() {
    delete_option( 'wpbp_reader_settings' );
    delete_option( 'wpbp_reader_upgrades' );
}

register_activation_hook( __FILE__, 'wpbp_reader_activate' );
add_action( 'plugins_loaded', 'wpbp_reader_maybe_upgrade' );
register_uninstall_hook( __FILE__, 'wpbp_reader_uninstall' );
"}}

