function wpbp_reader_plugin_action_links( $links ) {
    $settings_url = admin_url( 'options-general.php?page=wpbp-reader' );
    $settings_link = '<a href="' . esc_url( $settings_url ) . '">' . esc_html__( 'Settings', 'wpbp-reader' ) . '</a>';

