function wpbp_post_types_taxonomy_005( string $name ): array {
	$taxonomy   = 'wpbp_taxonomy_005';
	$registered = false;

	if ( ! taxonomy_exists( $taxonomy ) ) {
		register_taxonomy(
			$taxonomy,
			'post',
			array(
				'label'        => 'WPBP Taxonomy 005',
				'public'       => false,
				'show_ui'      => false,
				'show_in_rest' => false,
				'rewrite'      => false,
				'query_var'    => false,
				'hierarchical' => false,
			)
		);
		$registered = true;
	}

	$term = null;

	$existing = term_exists( $name, $taxonomy );
	if ( $existing ) {
		$term_id = is_array( $existing ) && isset( $existing['term_id'] )
			? (int) $existing['term_id']
			: (int) $existing;
		$term = get_term( $term_id, $taxonomy );
	} else {
		$inserted = wp_insert_term( $name, $taxonomy );

		if ( is_wp_error( $inserted ) ) {
			if ( 'term_exists' === $inserted->get_error_code() ) {
				$data    = $inserted->get_error_data();
				$term_id = is_array( $data ) && isset( $data['term_id'] )
					? (int) $data['term_id']
					: (int) $data;
				$term = get_term( $term_id, $taxonomy );
			}
		} elseif ( isset( $inserted['term_id'] ) ) {
			$term = get_term( (int) $inserted['term_id'], $taxonomy );
		}
	}

	$slug = '';
	if ( $term instanceof WP_Term ) {
		$slug = $term->slug;
	} elseif ( ! is_wp_error( $term ) && is_object( $term ) && isset( $term->slug ) ) {
		$slug = $term->slug;
	}

	if ( $registered ) {
		if ( function_exists( 'unregister_taxonomy' ) ) {
			unregister_taxonomy( $taxonomy );
		} elseif ( function_exists( 'unregister_taxonomy_for_object_type' ) ) {
			unregister_taxonomy_for_object_type( $taxonomy, 'post' );
		}
	}

	return array(
		'slug'     => $slug,
		'taxonomy' => $taxonomy,
	);
}
