		return false;
	}

	if ( (int) get_option( 'default_category' ) === $term_id ) {
		return false;
	}

	$fallback_term = get_term( $fallback_term_id, 'category' );
	if ( ! $fallback_term || is_wp_error( $fallback_term ) || $term_id === $fallback_term_id ) {
		return false;
	}

	$object_ids = get_objects_in_term( $term_id, 'category' );
	if ( is_wp_error( $object_ids ) ) {
		return false;
	}

	foreach ( array_unique( array_map( 'intval', $object_ids ) ) as $object_id ) {
		$current_terms = wp_get_object_terms(
			$object_id,
			'category',
			array(
				'fields' => 'ids',
			)
		);

		if ( is_wp_error( $current_terms ) ) {
			return false;
		}

		$current_terms = array_values( array_unique( array_map( 'intval', $current_terms ) ) );
		$current_terms = array_values( array_diff( $current_terms, array( $term_id ) ) );

