<?php
function wpbp_queries_010( array $post_ids, string $meta_key ): array {
    if ( empty( $post_ids ) ) {
        return array();
    }

    $post_ids = array_values( array_unique( array_map( 'absint', $post_ids ) ) );

    if ( empty( $post_ids ) ) {
        return array();
    }

    update_meta_cache( 'post', $post_ids );

    $values = array();
    foreach ( $post_ids as $post_id ) {
        $values[ $post_id ] = get_post_meta( $post_id, $meta_key, true );
    }

    return $values;
}
