                foreach ( $headers as $name => $value ) {
                    if ( 0 === strcasecmp( $name, 'X-WPBP-Key' ) ) {
                        $key = $value;
                        break;
                    }
                }
            }
        }

        if ( null === $key ) {
            return $result;
