<?php
function wpbp_roles_caps_009( string $capability ): array {
    if ( '' === $capability ) {
        return array();
    }

    $users = get_users(
        array(
            'fields'      => 'all',
            'number'      => -1,
            'count_total' => false,
        )
    );

    $user_ids = array();

    foreach ( $users as $user ) {
        if ( ! $user instanceof WP_User ) {
            continue;
        }

        $user->get_role_caps();

        if ( ! empty( $user->allcaps[ $capability ] ) ) {
            $user_ids[] = (int) $user->ID;
        }
    }

    sort( $user_ids, SORT_NUMERIC );

    return $user_ids;
}
```

