<?php
add_filter(
    'map_meta_cap',
    function( $caps, $cap, $user_id, $args ) {
        if ( 'edit_post' !== $cap || empty( $args[0] ) ) {
            return $caps;
        }

        $post = get_post( $args[0] );
        if ( ! $post || 'wpbp_report' !== $post->post_type ) {
            return $caps;
        }

        $delegate = (int) get_post_meta( $post->ID, 'wpbp_delegate', true );
        if ( $delegate > 0 && $delegate === (int) $user_id ) {
            return array();
        }

        return $caps;
    },
    10,
    4
);
```

