function wpbp_settings_options_009( array $option_names ): array {
    if ( empty( $option_names ) ) {
        return array();
    }

    global $wpdb;

    $values = array();
    $names  = array();

    foreach ( $option_names as $option_name ) {
        $option_name = (string) $option_name;
        $values[ $option_name ] = false;
        $names[ $option_name ]  = $option_name;
    }

    if ( empty( $names ) ) {
        return $values;
    }

    $names        = array_values( $names );
    $placeholders = implode( ',', array_fill( 0, count( $names ), '%s' ) );
    $query        = "SELECT option_name, option_value FROM {$wpdb->options} WHERE option_name IN ($placeholders)";
    $results      = $wpdb->get_results( $wpdb->prepare( $query, $names ) );

    foreach ( $results as $row ) {
        $values[ $row->option_name ] = maybe_unserialize( $row->option_value );
    }

    return $values;
}
