<?php

function wpbp_theme_templates_007( array $block_styles ): array {
	if ( empty( $block_styles ) || ! function_exists( 'wp_style_engine_get_styles' ) ) {
		return array( '', '' );
	}

	$styles = wp_style_engine_get_styles( $block_styles );
	$css    = isset( $styles['css'] ) && is_string( $styles['css'] ) ? $styles['css'] : '';

	$classname_styles = wp_style_engine_get_styles(
		$block_styles,
		array(
			'convert_vars_to_classnames' => true,
		)
	);

	$classnames = array();

	foreach ( array( $styles, $classname_styles ) as $style_result ) {
		if ( empty( $style_result['classnames'] ) ) {
			continue;
		}

		if ( is_array( $style_result['classnames'] ) ) {
			$style_classnames = $style_result['classnames'];
		} else {
			$style_classnames = preg_split( '/\s+/', trim( (string) $style_result['classnames'] ) );
		}

		foreach ( $style_classnames as $classname ) {
			$classname = trim( (string) $classname );
			if ( '' !== $classname ) {
				$classnames[] = $classname;
			}
		}
	}

	$classnames = array_values( array_unique( $classnames ) );

	return array( trim( $css ), implode( ' ', $classnames ) );
}
