add_filter(
    'the_content',
    static function ( $content ) {
        if ( ! is_string( $content ) || ! has_blocks( $content ) ) {
            return $content;
        }

        $blocks = parse_blocks( $content );
        $real_block_count = 0;
        $second_block_index = null;

        foreach ( $blocks as $index => $block ) {
            if ( isset( $block['blockName'] ) && null !== $block['blockName'] ) {
                ++$real_block_count;

                if ( 2 === $real_block_count ) {
                    $second_block_index = $index;
                }
            }
        }

        if ( $real_block_count <= 2 || null === $second_block_index ) {
            return $content;
        }

        $promo = array(
            'blockName'    => 'core/paragraph',
            'attrs'        => array( 'className' => 'wpbp-promo' ),
            'innerBlocks'  => array(),
            'innerHTML'    => '<p class="wpbp-promo">Sponsored by WPBP</p>',
            'innerContent' => array( '<p class="wpbp-promo">Sponsored by WPBP</p>' ),
        );

        array_splice( $blocks, $second_block_index + 1, 0, array( $promo ) );

        return serialize_blocks( $blocks );
    },
    1
);
